global.set("OPERADOR_GLOBAL_VARIABLE",{});

func:
switch (msg.topic) {
    // CEMENTO
    case "ns=5;i=270":
        global.set("REPORTES_GLOBAL_VARIABLE.REGISTRO_ALMACENADO", msg.payload);
    break;

    case "ns=5;i=271":
        global.set("REPORTES_GLOBAL_VARIABLE.REGISTRO_PENDIENTE", msg.payload);
    break;

    case "ns=5;i=272":
        global.set("REPORTES_GLOBAL_VARIABLE.REPORTE_PENDIENTE_SERIALIZADO", msg.payload);
    break;

    case "ns=5;i=275":
        global.set("REPORTES_GLOBAL_VARIABLE.REPORTE_PENDIENTE_NO_SERIALIZADO", msg.payload);
    break;
};

return msg;

